mapper.sql:
where b.status = 'completed'
  and b.import_type in ('knowledge_point', 'question', 'document_chunk')
and b.create_by = #{visibleUserId}

mapper.select:
select from cm_import_batch b
left join sys_user u on u.user_id = b.create_by
order by b.finished_time ascdesc, b.id ascdesc limit #{limit} offset #{offset}

select , cast(b.document_id as varchar) as document_id, b.valid_count, b.warning_count, b.failed_count, b.generated_count from cm_import_batch b
left join sys_user u on u.user_id = b.create_by
and b.id = #{id}

select concat(ec.certification_name, ' · ', sv.version_name)
from cm_syllabus_version sv join cm_exam_certification ec on ec.id=sv.certification_id
where sv.id=#{id}

select subject_no from (
    select es.id,row_number() over(order by case es.subject_code
        when 'COMPREHENSIVE' then 1
        when 'CASE_ANALYSIS' then 2
        when 'ESSAY' then 3
        else 999
    end,es.id)::int as subject_no
    from cm_exam_subject es join cm_syllabus_version sv on sv.certification_id=es.certification_id
    where sv.id=#{syllabusVersionId}
) x where id=#{subjectId}

select kp.exam_subject_id, kp.syllabus_number, kp.syllabus_title
from cm_knowledge_point kp
join cm_import_batch b on b.id = #{batchId}
left join cm_document d on d.id = b.document_id
where kp.syllabus_version_id = coalesce(b.syllabus_version_id, d.syllabus_version_id)
  and kp.del_flag = '0'
  and kp.exam_subject_id in
#{subjectId}
  and kp.syllabus_number in
#{number}

select import_batch_id,certification_id,collection_name,collection_type,duration_minutes,
       exam_year,exam_month,paper_type_code,paper_type_name,collection_id,collection_revision_id
from cm_paper_import where import_batch_id=#{batchId}

mapper.insert:
insert into cm_document(
    id, certification_id, syllabus_version_id, title, document_type, edition, status, del_flag,
    create_by, create_dept, update_by, create_time, update_time
) values (
    #{id}, #{certificationId}, #{syllabusVersionId}, #{title}, 'textbook', #{edition}, 'draft', '0',
    #{userId}, #{deptId}, #{userId}, #{createTime}, #{createTime}
)

insert into cm_import_batch(
    id, request_id, document_id, certification_id, syllabus_version_id, source_file_path, source_file_hash, source_file_name,
    source_file_size, source_file_mime, import_type, template_version, parser_version,
    parse_config, status, generated_count, create_by, create_dept, create_time
) values (
    #{id}, #{requestId}, #{documentId}, #{certificationId}, #{syllabusVersionId}, #{sourceFilePath}, #{sourceFileHash}, #{sourceFileName},
    #{sourceFileSize}, #{sourceFileMime}, 'document_chunk', 'document_chunk/1.0',
    'document-chunk-precheck/1.0', cast(#{parseConfig} as jsonb), 'uploaded', 0,
    #{userId}, #{deptId}, #{createTime}
)

mapper.sql:
where d.import_batch_id=#{batchId}
and d.exam_subject_id=#{examSubjectId}
and d.resolution_status=#{resolutionStatus}
and d.action=#{action}
and d.action <> 'unchanged'
and d.match_score>=#{minScore}
and d.match_score<=#{maxScore}

mapper.select:
select count(*) from cm_knowledge_import_diff
where import_batch_id=#{batchId} and confirmed_knowledge_point_id=#{knowledgePointId}
  and id<>#{excludeDiffId}

mapper.update:
update cm_knowledge_point kp set parent_id=v.parent_id,syllabus_number=v.syllabus_number,syllabus_title=v.syllabus_title, tree_depth=v.tree_depth,sort_order=v.sort_order,description=v.description,importance=v.importance, recommendation_enabled=true,status=v.status, del_flag='0',update_by=v.user_id,update_time=now() from (values
(#{row.id}::bigint,#{row.parentId}::bigint,#{row.syllabusNumber}::varchar, #{row.syllabusTitle}::varchar,#{row.treeDepth}::smallint,#{row.sortOrder}::integer, #{row.description}::text,#{row.importance}::smallint,#{row.status}::char(1),#{row.userId}::bigint)
) as v(id,parent_id,syllabus_number,syllabus_title,tree_depth,sort_order,description,importance,status,user_id) where kp.id=v.id

mapper.delete:
delete from cm_document_image where chunk_id in (
    select id from cm_document_chunk where document_id = #{documentId}
)

delete from cm_chunk_knowledge where chunk_id in (
    select id from cm_document_chunk where document_id = #{documentId}
)

mapper.update:
update cm_import_record r set result_data = cast(v.result_data as jsonb), status = 'success', processed_time = now() from (values
(#{row.id}::bigint, #{row.resultData}::text)
) as v(id, result_data) where r.id = v.id and r.status = 'pending'

mapper.sql:
where i.import_batch_id = #{batchId}
and i.severity = #{severity}
and i.issue_code = #{issueCode}
